# ==========================================
# 1. HELPER CLASSES UNTUK DYNAMIC PARSING
# ==========================================

class SafeFallback(str):
    """
    Mengembalikan string kosong secara aman
    jika data terdalam tidak ditemukan.
    """

    def __getattr__(self, name: str) -> "SafeFallback":
        return SafeFallback("")

    def __getitem__(self, key: Any) -> "SafeFallback":
        return SafeFallback("")


class DeepParsedList(list):
    """
    Memungkinkan akses array index menggunakan
    dot-notation:

    {output.0.id}
    {output.1.document_id}
    """

    def __getattr__(self, index: str) -> Any:
        try:
            idx = int(index)
            return self[idx]
        except (ValueError, IndexError):
            return SafeFallback("")

    def __getitem__(self, index: Any) -> Any:
        try:
            return super().__getitem__(index)
        except (IndexError, TypeError):
            return SafeFallback("")


def _recursive_wrap(data: Any) -> Any:
    """
    Membungkus list dan dict agar bisa diparse
    menggunakan dot-notation.
    """

    if isinstance(data, dict):
        return DeepParsedDict(data)

    elif isinstance(data, list):
        return DeepParsedList(
            [_recursive_wrap(item) for item in data]
        )

    # Langflow Data Unpacker
    elif hasattr(data, "data") and isinstance(data.data, dict):
        return _recursive_wrap(data.data)

    return data


class DeepParsedDict(dict):
    """
    Dictionary dengan akses dot-notation
    tanpa batas kedalaman.
    """

    def __init__(self, data_map: dict):
        super().__init__()

        if not isinstance(data_map, dict):
            return

        for key, value in data_map.items():
            self[key] = _recursive_wrap(value)

    def __getattr__(self, key: str) -> Any:
        value = self.get(key)

        return (
            SafeFallback("")
            if value is None
            else value
        )

    def __missing__(self, key: str) -> Any:
        return SafeFallback("")


