    # ==========================================
    # COLLECTION NAME PARSER
    # ==========================================

    def _get_collection_name(self) -> str:
        """
        Mengambil Collection Name dari input.

        Mendukung beberapa bentuk:

        1. String langsung:
           "documents"

        2. Langflow Data:
           Data(data={"collection_name": "documents"})

        3. Dictionary:
           {"collection_name": "documents"}

        4. Object yang mempunyai .text

        5. Object yang mempunyai .content
        """

        value = self.collection_name

        # --------------------------------------
        # Langflow Data
        # --------------------------------------

        if hasattr(value, "data"):
            data = value.data

            if isinstance(data, dict):
                value = data.get(
                    "collection_name",
                    data.get("name", ""),
                )

            elif data is not None:
                value = data

        # --------------------------------------
        # Dictionary
        # --------------------------------------

        elif isinstance(value, dict):
            value = value.get(
                "collection_name",
                value.get("name", ""),
            )

        # --------------------------------------
        # Object dengan .text
        # --------------------------------------

        elif hasattr(value, "text"):
            text = getattr(value, "text", None)

            if text:
                value = text

        # --------------------------------------
        # Object dengan .content
        # --------------------------------------

        elif hasattr(value, "content"):
            content = getattr(value, "content", None)

            if content:
                value = content

        # --------------------------------------
        # Normalisasi
        # --------------------------------------

        if value is None:
            value = ""

        value = str(value).strip()

        # --------------------------------------
        # Jika ternyata input berupa JSON
        # --------------------------------------

        if value.startswith("{") and value.endswith("}"):
            try:
                parsed = json.loads(value)

                if isinstance(parsed, dict):
                    value = parsed.get(
                        "collection_name",
                        parsed.get("name", ""),
                    )

            except Exception:
                pass

        value = str(value).strip()

        # --------------------------------------
        # Validasi
        # --------------------------------------

        if not value:
            raise ValueError(
                "Collection Name tidak boleh kosong."
            )

        return value

    # ==========================================
    # EKSTRAKSI DAN STANDARDISASI DATA
    # ==========================================

    def _extract_source_data(self) -> dict:

        source_dict = {}

        target_input = self.input_data

        if not target_input:
            return source_dict

        # --------------------------------------
        # JSON PARSER
        # --------------------------------------

        def try_parse_json(val: Any) -> Any:

            if isinstance(val, str):

                val_stripped = val.strip()

                if val_stripped.startswith(
                    ("{", "[")
                ):
                    try:
                        return json.loads(
                            val_stripped
                        )
                    except Exception:
                        pass

            return val

        target_input = try_parse_json(
            target_input
        )

        # ======================================
        # DATAFRAME
        # ======================================

        if (
            isinstance(target_input, pd.DataFrame)
            or type(target_input).__name__
            == "DataFrame"
        ):

            records = target_input.to_dict(
                orient="records"
            )

            source_dict["tabel"] = records
            source_dict["list"] = records
            source_dict["output"] = records

            if records:
                source_dict.update(records[0])

        # ======================================
        # LIST
        # ======================================

        elif isinstance(target_input, list):

            clean_list = []

            for item in target_input:

                if (
                    hasattr(item, "data")
                    and isinstance(item.data, dict)
                ):
                    clean_list.append(
                        item.data
                    )

                elif isinstance(item, dict):
                    clean_list.append(item)

                else:
                    clean_list.append(item)

            source_dict["tabel"] = clean_list
            source_dict["list"] = clean_list
            source_dict["output"] = clean_list

            if (
                len(clean_list) > 0
                and isinstance(
                    clean_list[0],
                    dict,
                )
            ):
                source_dict.update(
                    clean_list[0]
                )

        # ======================================
        # LANGFLOW DATA
        # ======================================

        elif (
            hasattr(target_input, "data")
            and isinstance(
                target_input.data,
                dict,
            )
        ):

            source_dict.update(
                target_input.data
            )

            source_dict["data"] = dict(
                target_input.data
            )

            source_dict["output"] = [
                dict(target_input.data)
            ]

        # ======================================
        # DICTIONARY
        # ======================================

        elif isinstance(target_input, dict):

            source_dict.update(
                target_input
            )

            if "output" not in source_dict:
                source_dict["output"] = [
                    target_input
                ]

        # ======================================
        # TEXT / MESSAGE
        # ======================================

        else:

            text_content = ""

            if (
                hasattr(target_input, "text")
                and isinstance(
                    target_input.text,
                    str,
                )
            ):
                text_content = target_input.text

            elif (
                hasattr(target_input, "content")
                and isinstance(
                    target_input.content,
                    str,
                )
            ):
                text_content = target_input.content

            elif isinstance(
                target_input,
                str,
            ):
                text_content = target_input

            if text_content:

                parsed_text = try_parse_json(
                    text_content
                )

                if isinstance(
                    parsed_text,
                    dict,
                ):

                    source_dict.update(
                        parsed_text
                    )

                elif isinstance(
                    parsed_text,
                    list,
                ):

                    source_dict["output"] = (
                        parsed_text
                    )

                    if (
                        len(parsed_text) > 0
                        and isinstance(
                            parsed_text[0],
                            dict,
                        )
                    ):
                        source_dict.update(
                            parsed_text[0]
                        )

                else:

                    source_dict["text"] = (
                        text_content
                    )

        # ======================================
        # TEXT -> PROMPT
        # ======================================

        if (
            "text" in source_dict
            and "prompt" not in source_dict
        ):
            source_dict["prompt"] = (
                source_dict["text"]
            )

        return source_dict

    # ==========================================
    # GENERATE ASTRA DB FILTER
    # ==========================================

    def _generate_parsed_dict(self) -> dict:

        source_data = (
            self._extract_source_data()
        )

        formatted_source = DeepParsedDict(
            source_data
        )

        result_filter = {}

        if not self.filter_table:
            return result_filter

        # ======================================
        # LOOP FILTER TABLE
        # ======================================

        for row in self.filter_table:

            if not (
                isinstance(row, dict)
                and "key" in row
                and "value" in row
            ):
                continue

            raw_k = str(
                row.get("key") or ""
            ).strip()

            value = row.get(
                "value",
                "",
            )

            if not raw_k:
                continue

            # ==================================
            # PARSE KEY
            # ==================================

            key = raw_k

            if (
                "{" in key
                and "}" in key
            ):

                try:

                    key = key.format_map(
                        formatted_source
                    )

                except Exception:

                    key = raw_k

            key = key.strip()

            if not key:
                continue

            # ==================================
            # PARSE VALUE
            # ==================================

            formatted_value = value

            if isinstance(
                value,
                str,
            ):

                value_trimmed = (
                    value.strip()
                )

                # ------------------------------
                # Dynamic variable
                # ------------------------------

                if (
                    "{"
                    in value_trimmed
                    and "}"
                    in value_trimmed
                ):

                    try:

                        formatted_value = (
                            value_trimmed.format_map(
                                formatted_source
                            )
                        )

                    except Exception:

                        formatted_value = (
                            value_trimmed
                        )

                # ------------------------------
                # Type conversion
                # ------------------------------

                if isinstance(
                    formatted_value,
                    str,
                ):

                    value_lower = (
                        formatted_value.lower()
                    )

                    if value_lower == "true":

                        formatted_value = True

                    elif value_lower == "false":

                        formatted_value = False

                    elif value_lower in (
                        "null",
                        "none",
                    ):

                        formatted_value = None

                    elif formatted_value.isdigit():

                        formatted_value = int(
                            formatted_value
                        )

            # ==================================
            # ADD FILTER
            # ==================================

            result_filter[key] = (
                formatted_value
            )

        return result_filter

    # ==========================================
    # MAIN SEARCH METHOD
    # ==========================================

    def search_metadata(self) -> DataFrame:

        # ======================================
        # 1. COLLECTION NAME
        # ======================================

        collection_name = (
            self._get_collection_name()
        )

        # ======================================
        # 2. BUILD FILTER
        # ======================================

        actual_filter = (
            self._generate_parsed_dict()
        )

        # ======================================
        # 3. CONNECT ASTRA DB
        # ======================================

        try:

            client = DataAPIClient(
                self.token
            )

            database = (
                client.get_database_by_api_endpoint(
                    self.api_endpoint
                )
            )

            # ----------------------------------
            # Dengan namespace
            # ----------------------------------

            if self.namespace:

                collection = (
                    database.get_collection(
                        collection_name,
                        keyspace=self.namespace,
                    )
                )

            # ----------------------------------
            # Tanpa namespace
            # ----------------------------------

            else:

                collection = (
                    database.get_collection(
                        collection_name
                    )
                )

        except Exception as e:

            raise ValueError(
                "Gagal terhubung atau mengambil "
                f"collection '{collection_name}': {e}"
            ) from e

        # ======================================
        # 4. EXECUTE ASTRA DB SEARCH
        # ======================================

        try:

            cursor = collection.find(
                filter=actual_filter,
                projection={
                    "_id": 1,
                    "metadata": 1,
                },
                limit=(
                    self.limit
                    if self.limit > 0
                    else 1000
                ),
            )

            # ==================================
            # 5. FORMAT RESULT
            # ==================================

            data_results = []

            for doc in cursor:

                data_results.append(
                    {
                        "_id": str(
                            doc.get(
                                "_id",
                                "",
                            )
                        ),
                        "metadata": doc.get(
                            "metadata",
                            {},
                        ),
                    }
                )

            # ==================================
            # 6. DATAFRAME
            # ==================================

            df_result = DataFrame(
                data_results
            )

            # ==================================
            # 7. LANGFLOW STATUS
            # ==================================

            self.status = (
                f"Collection: {collection_name}\n"
                f"Filter Dieksekusi: "
                f"{actual_filter}\n"
                f"Total Ditemukan: "
                f"{len(data_results)} dokumen."
            )

            return df_result

        except Exception as e:

            raise ValueError(
                "Error saat mengeksekusi "
                f"pencarian: {e}"
            ) from e
